def select(jobs):
    result=[]
    for i in sorted(range(len(jobs)),key=lambda i:-jobs[i][2]):
        a,b,_=jobs[i]
        if all(b<=jobs[j][0] or a>=jobs[j][1] for j in result):
            result.append(i)
    return tuple(sorted(result))

