from solution import select
import random, itertools
rng=random.Random(348)
def oracle(jobs):
    valid=[]
    for mask in range(1<<len(jobs)):
        idx=tuple(i for i in range(len(jobs)) if mask>>i&1)
        if all(jobs[i][1]<=jobs[j][0] or jobs[j][1]<=jobs[i][0] for i,j in itertools.combinations(idx,2)):
            valid.append((sum(jobs[i][2] for i in idx),idx))
    best=max(v[0] for v in valid)
    return min(v[1] for v in valid if v[0]==best)
assert select([(0,3,7),(0,1,4),(1,3,4)])==(1,2)
for _ in range(100):
    jobs=[(a,a+rng.randrange(1,5),rng.randrange(0,6)) for a in [rng.randrange(-2,8) for _ in range(rng.randrange(0,9))]]
    before=list(jobs); assert select(jobs)==oracle(jobs),(jobs,select(jobs),oracle(jobs)); assert jobs==before
for jobs in [[(2,2,1)],[(3,1,0)],[(0,1,-1)]]:
    try: select(jobs)
    except ValueError: pass
    else: raise AssertionError(jobs)
assert select([(i,i+1,1) for i in range(1200)])==tuple(range(1200))

