class Decoder:
    def __init__(self):
        self.buffer=b''
    def feed(self, chunk):
        self.buffer+=chunk
        if len(self.buffer)<4: return []
        n=int.from_bytes(self.buffer[:4],'big')
        if len(self.buffer)<4+n: return []
        value=self.buffer[4:4+n].decode('utf8')
        self.buffer=b''
        return [value]
    def finish(self):
        return None

