import random
texts=['','èα🙂','hello','x'*64,'z']
data=b''.join(len(s.encode()).to_bytes(4,'big')+s.encode() for s in texts)
for step in range(1,len(data)+1):
    d=Decoder(); out=[]
    for p in range(0,len(data),step): out+=d.feed(data[p:p+step])
    assert out==texts,(step,out)
    assert d.finish() is None
    for action in [lambda:d.feed(b''),d.finish]:
        try: action()
        except ValueError: pass
